#ifndef __HEAVYWEAPON_GAMETEXT_H__
#define __HEAVYWEAPON_GAMETEXT_H__

// Heavy Weapon's texts (titles, messages, the help screen, the stats screen's labels, the default high-score names) are
// hard-coded in its exe. port: by the user's decision (2026-10-19) no game text is in the repository: the port reads
// them from the player's own executable, by address, and a mod or language pack can replace any of them.
//
// - GameTextTable.inc (generated by games/heavyweapon/tools/make_gametext.py from the GT(0x...) addresses the source
//   names) lists each string's address in the game image, its length and a hash: no text.
// - LoadGameTexts() reads the game folder's executable (the Steam copy's Heavy Weapon Deluxe.exe holds the game's image
//   inside its launcher), finds the game image in it (the one whose texts match), reads each text at its address and
//   checks length and hash. A text that does not match (another version of the exe) stays empty and is logged.
// - Code names a text by its address in the original: GT(0x0052a8b8). Overrides: any string property named
//   GT_<8 hex digits> (e.g. <String id="GT_0052a8b8">...</String> from a mod) replaces the text read from the exe.

#include "Common.h"

namespace Sexy
{

// The executable in theDir the texts are read from ("" when there is none): Heavy Weapon Deluxe.exe (Steam) or
// HeavyWeapon.exe
std::string			FindGameExecutable(const std::string& theDir);

// Reads the texts from the game folder's executable and applies the string-property overrides. Returns false when
// the executable is missing or no text matched (the texts are then empty or overrides only).
bool				LoadGameTexts();
// The text the original keeps at theVA; "" for an address that is not in the table
const SexyString&	GameText(unsigned int theVA);

#define GT(theVA) (::Sexy::GameText(theVA))
#define GTC(theVA) (::Sexy::GameText(theVA).c_str())
// A text's address kept in a table, for GT later (make_gametext.py finds these too)
#define GTA(theVA) (theVA)

}

#endif
